fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len();

    // Binary search for the first occurrence of target
    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            left = mid + 1;
        } else {
            // arr[mid] >= target
            right = mid;
        }
    }

    // After the loop, left == right is the smallest index where arr[left] >= target
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}